// Rattache chaque chunk au document qui vient d'être créé (le nœud précédent renvoie l'identifiant du document)
const id = $input.first().json.id;
return $('When Executed by Another Workflow').all().map(i => ({ json: { ...i.json, document_id: id } }));

// Regroupe le lot en UNE requête d'embedding (sinon le nœud HTTP ferait un appel par chunk)
const chunks = $input.all().map(i => i.json);
return [{ json: { chunks, requests: chunks.map(c => ({ model: 'models/gemini-embedding-001', content: { parts: [{ text: c.texte_embedding }] } })) } }];

// Associe chaque vecteur à son chunk. Garde-fou : l'API gratuite peut renvoyer des vecteurs vides sans erreur.
const { chunks } = $('Préparer embedding').first().json;
const emb = $input.first().json.embeddings || [];
if (emb.length !== chunks.length) throw new Error('Embeddings incomplets : ' + emb.length + ' vecteurs pour ' + chunks.length + ' chunks');
const vides = emb.filter(e => !e.values || !e.values.length).length;
if (vides) throw new Error(vides + ' vecteur(s) vide(s) renvoyé(s) par l\'API d\'embedding (limite de débit ?)');

const lignes = chunks.map((c, i) => ({
  ordre: c.ordre, content: c.texte, contexte: c.contexte, resume: c.resume, questions: c.questions,
  metadata: { collection: c.collection, source: c.source, titre: c.titre, entites: c.entites.map(e => e.nom), mots_cles: c.mots_cles },
  embedding: '[' + emb[i].values.join(',') + ']',
  mots_cles: c.mots_cles, entites: c.entites, relations: c.relations
}));
return [{ json: { lignes: JSON.stringify(lignes), document_id: chunks[0].document_id } }];

// Bilan renvoyé à l'orchestrateur quand tous les lots sont enregistrés
const chunks = $('Associer le document aux chunks').all();
return [{ json: { ok: true, document_id: chunks[0].json.document_id, source: chunks[0].json.source, collection: chunks[0].json.collection, chunks: chunks.length } }];
